"""Cleaning step of the orders ETL."""

import pandas as pd
from pandas.api.types import is_object_dtype, is_string_dtype


def _clean_text(value):
    if isinstance(value, str):
        value = value.strip()
        return pd.NA if value == "" else value
    return value


def clean_orders(df: pd.DataFrame) -> pd.DataFrame:
    """A copy of ``df`` with text trimmed, blank text missing and missing qty 0."""
    out = df.copy()
    for col in out.columns:
        s = out[col]
        if is_object_dtype(s.dtype):
            # Mixed columns: only touch the str cells, leave everything else as is.
            out[col] = s.map(_clean_text)
        elif is_string_dtype(s.dtype):
            s = s.str.strip()
            out[col] = s.mask(s == "")
    if "qty" in out.columns:
        out["qty"] = out["qty"].fillna(0)
    return out

